import assert from 'node:assert/strict'

export async function verifyFourthUi({go,title,click,set,evaluate,send,wait,width,capture,tab,body,report}){
 const byLabel=label=>label==='검색 목록 닫기'?evaluate('document.querySelector(".record-search input").dispatchEvent(new KeyboardEvent("keydown",{key:"Escape",bubbles:true}))'):label==='검색 목록 열기'?evaluate('document.querySelector(".record-search input").click();document.querySelector(".record-search input").focus()'):evaluate('document.querySelector('+JSON.stringify('button[aria-label="'+label+'"]')+').click()')
 const dialog='dialog[open]:not(:has(dialog[open]))'
 await go('/routine-preview?tab=history&review=approval');await title('운동 기록 요약')
 for(const w of [320,375,390,430]){
  await width(w,'react')
  const buttons=await evaluate('[...document.querySelectorAll(".approval-toolbar button")].map(b=>({text:b.textContent,w:b.getBoundingClientRect().width,h:b.getBoundingClientRect().height}))')
  assert.deepEqual(buttons.map(b=>b.text),['전체 승인']);assert(buttons[0].h<=40)
 }
 await click('무게 수정')
 await wait(()=>evaluate('!!document.querySelector(".approval-draft-value")'),'approval modal')
 const colors=()=>evaluate('(()=>{const p=document.querySelector(".approval-draft-value");return{before:getComputedStyle(p).color,after:getComputedStyle(p.querySelector("strong")).color,text:p.textContent}})()')
 assert.equal((await colors()).before,'rgb(240, 241, 244)');assert.equal((await colors()).after,'rgb(116, 166, 138)')
 await click('−2.5');await click('−2.5');await click('−2.5');assert.equal((await colors()).after,'rgb(214, 188, 101)')
 await click('취소');assert.match(await evaluate('document.querySelector(".approval-values").textContent'),/25kg → 30kg/)
 await click('무게 수정');await byLabel('승인 예정 중량')
 await wait(()=>evaluate('!!document.querySelector("[data-wheel-selection]")'),'continuous wheel')
 for(const w of [320,375,390,430]){
  await capture('fourth-number-wheel','react',w)
  await evaluate('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')
  const wheel=await evaluate('(()=>{const selected=document.querySelector("dialog[open]:not(:has(dialog[open])) [aria-pressed=true]"),other=selected.previousElementSibling,marker=document.querySelector("[data-wheel-selection]"),r=selected.getBoundingClientRect(),m=marker.getBoundingClientRect(),c=getComputedStyle(selected),o=getComputedStyle(other);return{background:c.backgroundColor,radius:c.borderRadius,border:c.borderTopWidth,center:Math.abs(r.top+r.height/2-m.top-m.height/2),selectedOpacity:Number(c.opacity),otherOpacity:Number(o.opacity),font:parseFloat(c.fontSize)>parseFloat(o.fontSize),snap:getComputedStyle(selected.parentElement).scrollSnapType}})()')
  assert.equal(wheel.background,'rgba(0, 0, 0, 0)');assert.equal(wheel.radius,'0px');assert.equal(wheel.border,'0px');assert(wheel.center<1);assert(wheel.selectedOpacity>wheel.otherOpacity);assert(wheel.font);assert.equal(wheel.snap,'y mandatory')
 }
 await width(375,'react');await send('Emulation.setTouchEmulationEnabled',{enabled:true})
 const location=await evaluate('(()=>{const r=document.querySelector("[data-wheel-selection]").getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()')
 await evaluate('(()=>{const s=document.querySelector("dialog[open]:not(:has(dialog[open])) [aria-pressed=true]").parentElement;window.fourthWheelEvents=[];for(const name of ["pointerdown","touchstart","scroll"])s.addEventListener(name,e=>window.fourthWheelEvents.push([e.type,s.scrollTop]))})()')
 await send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[location]})
 for(let i=1;i<=6;i++)await send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:location.x,y:location.y-i*16}]})
 await send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]})
 await wait(()=>evaluate('document.querySelector("dialog[open]:not(:has(dialog[open])) [aria-pressed=true]").textContent.trim()!=="30 kg"'),'wheel touch scroll selects a new value')
 await click('확인',dialog+' button');await click('취소',dialog+' button')
 assert.match(await evaluate('document.querySelector(".approval-values").textContent'),/25kg → 30kg/)
 await tab('기록');await title('이번 주 요약')
 const cards=await evaluate('[...document.querySelectorAll(".recent-records .session-record-card")].map(b=>({id:b.dataset.sessionId,date:b.querySelector("time").textContent}))')
 assert(cards.length>0);assert.equal(cards.length,new Set(cards.map(c=>c.id)).size);assert(cards.every(c=>c.date.slice(0,5)>='11.05'&&c.date.slice(0,5)<='11.11'))
 assert.doesNotMatch(await body(),/운동 기록 요약 보기/)
 const captured=cards.find(c=>!c.id.startsWith('20000000-'));assert(captured);await evaluate('document.querySelector('+JSON.stringify('[data-session-id="'+captured.id+'"].session-record-card')+').click()');await title('운동 기록 상세')
 const oldReview=await evaluate('(()=>{const c=document.querySelector("[aria-label=\\"당시 중량 검토\\"]");return c?{text:c.textContent,buttons:c.querySelectorAll("button").length,inputs:c.querySelectorAll("input").length}:null})()')
 assert(oldReview);assert.match(oldReview.text,/25kg/);assert.equal(oldReview.buttons,0);assert.equal(oldReview.inputs,0);assert.match(await body(),/WEIGHT.*CARDIO/s)
 await click('기록으로');await tab('홈')
 assert.equal(await evaluate('document.querySelector(\'section[aria-label="홈"] [data-session-id]\').dataset.sessionId'),captured.id)
 assert.equal(await evaluate('document.querySelectorAll(\'section[aria-label="홈"] [data-session-id] [class*=recordState] small\').length'),0)
 await evaluate('document.querySelector("section[aria-label=최근\\ 운동] button").click()').catch(()=>click('전체 보기 ›'))
 await title('전체 운동 이력');await send('Runtime.evaluate',{expression:'history.back()'})
 await wait(()=>evaluate('!!document.querySelector("section[aria-label=홈]")'),'home history back')
 for(const w of [320,375,390,430]){
  await width(w,'react');const paddings=[]
  for(const name of ['홈','루틴','기록']){await tab(name);paddings.push(await evaluate('(()=>{const m=document.querySelector("main"),c=getComputedStyle(m);return[m.getBoundingClientRect().width,c.paddingLeft,c.paddingRight]})()'))}
  assert.deepEqual(paddings[0],paddings[1]);assert.deepEqual(paddings[1],paddings[2])
 }
 await click('전체 보기 ›');await title('전체 운동 이력')
 await set('.record-search select','exercise');await set('.record-search input','벤치')
 await wait(()=>evaluate('!!document.querySelector(".record-search li button")'),'history candidate')
 await evaluate('document.querySelector(".record-search li button").click()')
 const chosenRows=await evaluate('[...document.querySelectorAll(".session-record-card")].map(c=>c.dataset.sessionId)')
 await set('.record-search input','');assert.deepEqual(await evaluate('[...document.querySelectorAll(".session-record-card")].map(c=>c.dataset.sessionId)'),chosenRows,'clearing a search draft does not silently remove the selected filter')
 await byLabel('검색 목록 닫기');assert.deepEqual(await evaluate('[...document.querySelectorAll(".session-record-card")].map(c=>c.dataset.sessionId)'),chosenRows)
 await byLabel('선택 해제');await tab('기록')
 await click('운동 현황 ›');await title('운동 현황')
 await set('.record-search select','exercise');await set('.record-search input','벤치')
 await wait(()=>evaluate('!!document.querySelector(".record-search li button")'),'trend candidate');await evaluate('document.querySelector(".record-search li button").click()')
 const filter=await evaluate('document.querySelector(".record-search input").value')
 await byLabel('검색 목록 열기');const searchButton=await evaluate('(()=>{const b=document.querySelector(".search-disclosure"),r=b.getBoundingClientRect(),c=getComputedStyle(b);return{w:r.width,h:r.height,radius:c.borderRadius,border:c.borderTopWidth,color:c.color}})()');assert.equal(searchButton.w,searchButton.h);assert.equal(searchButton.radius,'50%');assert.equal(searchButton.border,'1px');assert.equal(searchButton.color,'rgb(108, 147, 198)');await byLabel('검색 목록 닫기');assert.equal(await evaluate('document.querySelector(".record-search input").value'),filter)
 await set('.record-preview-controls select','loading');await evaluate('document.querySelector(".record-statistics-body .app-card").setAttribute("data-fourth-stable","yes")')
 assert.equal(await evaluate('!!document.querySelector("[data-fourth-stable]") && !document.querySelector("[data-loading-skeleton=activity]")'),true,'same-period revalidation retains its cards')
 const pendingPeriod = '.record-period[data-layout="activity"] .record-tabs'
 const displayedSets = await evaluate('document.querySelector(`[aria-label="운동량 요약"] strong`).textContent')
 await click('월간')
 assert.equal(await evaluate(`document.querySelector('${pendingPeriod} button[aria-pressed="true"]').textContent`),'주간')
 assert.equal(await evaluate(`document.querySelector('${pendingPeriod} button[aria-busy="true"]').textContent`),'월간')
 assert.equal(await evaluate('document.querySelector(`[aria-label="운동량 요약"] strong`).textContent'),displayedSets)
 assert.equal(await evaluate('!!document.querySelector("[data-fourth-stable]") && !document.querySelector("[data-loading-skeleton=activity]")'),true)
 await wait(()=>evaluate(`document.querySelector('${pendingPeriod} button[aria-pressed="true"]').textContent === '월간'`),'monthly statistics loaded')
 assert.equal(await evaluate('document.querySelectorAll("[data-week-day]").length'),7);assert.equal(await evaluate('document.querySelectorAll("[data-week-day] > time:first-child").length'),7);assert.equal(await evaluate('document.querySelector(".record-data-range")'),null);assert.equal(await evaluate('document.querySelector(".record-search input").value'),filter)
 await byLabel('달력 열기')
 const calendar=await evaluate('(()=>{const b=document.querySelector(".record-calendar-trigger"),c=[...document.querySelectorAll(".record-calendar button")].find(b=>b.textContent==="닫기");return{active:getComputedStyle(b,"::before").backgroundColor,close:getComputedStyle(c).color,background:getComputedStyle(c).backgroundColor}})()')
 assert.equal(calendar.active,'rgb(108, 147, 198)');assert.equal(calendar.close,'rgb(240, 183, 191)');assert.equal(calendar.background,'rgba(0, 0, 0, 0)')
 await click('닫기');await set('.record-preview-controls select','normal')
 await wait(()=>evaluate('!!document.querySelector(".record-statistics-body")'),'normal query')
 for(const w of [320,375,390,430]){await capture('fourth-activity-month','react',w)}
 await tab('기록');await click('성장 추적 ›');await title('성장 추적')
 assert.equal(await evaluate('document.querySelector(".search-selected")'),null);assert.match(await evaluate('document.querySelector(".record-search input").value'),/벤치/)
 for(const w of [320,375,390,430])await capture('fourth-growth','react',w)
 const fonts=await evaluate('(()=>{const root=document.querySelector(".app-shell"),family=getComputedStyle(root).fontFamily;return[...root.querySelectorAll("h1,h2,h3,p,button,input,select,label,svg text")].filter(e=>e.getClientRects().length&&getComputedStyle(e).fontFamily!==family).map(e=>({tag:e.tagName,font:getComputedStyle(e).fontFamily,text:e.textContent.slice(0,30)}))})()')
 assert.deepEqual(fonts,[])
 report.interactions.push('fourth UI: continuous touch wheel, equal approval header and edit mode, read-only frozen review, normalized recent cards, home full-history/back, consistent page gutters, preserved loading DOM, seven-day achievement, circular search and selected-filter separation, Onyx calendar/close/font checks at four widths')
}
